}
*{box-sizing:border-box}html{scroll-behavior:smooth;background:var(--bg)}body{margin:0;background:var(--bg);color:var(--text);font-family:var(--body);font-size:16px;line-height:1.5;overflow-x:hidden}body.menu-open{overflow:hidden}
a{color:inherit;text-decoration:none}button{font:inherit}img{display:block;width:100%;height:auto}figure{margin:0}.shell{width:min(var(--max),100%);margin-inline:auto;padding-inline:var(--pad)}
.skip{position:fixed;left:12px;top:12px;z-index:200;background:var(--paper);color:var(--ink);padding:10px 14px;transform:translateY(-140%);transition:.2s}.skip:focus{transform:none}
.nav{height:82px;position:fixed;z-index:90;top:0;left:0;right:0;display:grid;grid-template-columns:auto 1fr auto;align-items:center;padding:0 var(--pad);background:rgba(7,7,7,.78);backdrop-filter:blur(16px);border-bottom:1px solid rgba(255,255,255,.08)}
.brand{display:flex;align-items:center;gap:10px;font-weight:700;letter-spacing:-.04em;font-size:18px}.brand-mark{width:29px;height:29px;object-fit:contain}.nav-links{justify-self:end;display:flex;align-items:center;gap:clamp(18px,2vw,34px);font-size:13px}.nav-links a{position:relative;color:#d8d5d0;transition:color .2s}.nav-links a:hover,.nav-links a:focus-visible{color:white}.nav-links a[aria-current="page"]{color:white}.nav-cta{border:1px solid rgba(255,255,255,.26);padding:11px 16px;transition:background .25s var(--ease),color .25s var(--ease)!important}.nav-cta:hover{background:white;color:#0a0a0a!important}.menu-btn{display:none;width:46px;height:46px;background:none;border:1px solid rgba(255,255,255,.2);color:white;align-items:center;justify-content:center;cursor:pointer}.menu-btn span,.menu-btn:before{content:"";display:block;width:18px;height:1px;background:currentColor;position:absolute}.menu-btn span{transform:translateY(4px)}.menu-btn:before{transform:translateY(-4px)}
.mobile-menu{display:none;position:fixed;inset:82px 0 0;z-index:80;background:#070707;padding:32px var(--pad) 40px}.mobile-menu a{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding:18px 0;font-size:clamp(28px,7vw,42px);letter-spacing:-.04em}
.kicker{font-size:11px;text-transform:uppercase;letter-spacing:.19em;color:var(--muted)}
.hero{min-height:100svh;padding-top:82px;position:relative;display:flex;align-items:flex-end;overflow:hidden}.hero .shell{padding-top:clamp(78px,9vw,140px);padding-bottom:clamp(36px,5vw,70px)}.hero-meta{display:flex;justify-content:space-between;align-items:center;padding-bottom:28px;border-bottom:1px solid var(--line);margin-bottom:clamp(26px,4vw,54px)}.hero-meta span:last-child{color:#8e8b85;font-size:12px}
.hero-title{margin:0;max-width:1280px;font-size:clamp(62px,9.5vw,154px);line-height:.84;letter-spacing:-.075em;font-weight:560}.hero-title .accent{color:var(--red)}.hero-bottom{display:grid;grid-template-columns:1.35fr .65fr;gap:clamp(30px,5vw,90px);align-items:end;margin-top:clamp(34px,5vw,72px)}.hero-lead{margin:0;max-width:760px;color:#c8c4be;font-size:clamp(18px,1.55vw,25px);line-height:1.36;letter-spacing:-.02em}.hero-actions{display:flex;gap:14px;justify-content:flex-end;align-items:center}.btn{display:inline-flex;min-height:48px;align-items:center;justify-content:center;gap:10px;padding:13px 19px;border:1px solid rgba(255,255,255,.25);font-size:13px;transition:all .25s var(--ease)}.btn.primary{background:var(--red);border-color:var(--red);color:white}.btn:hover{transform:translateY(-2px);border-color:white}.btn.primary:hover{background:#f12557}.text-link{font-size:13px;border-bottom:1px solid currentColor;padding:11px 0;display:inline-flex;gap:12px;align-items:center}
.hero-stage{margin-top:clamp(36px,5vw,68px);position:relative;overflow:hidden;background:#151515;aspect-ratio:16/7.4}.hero-stage > img:first-child{width:100%;height:100%;object-fit:cover;object-position:50% 54%;transform:scale(1.035);will-change:transform}.hero-slash{position:absolute!important;z-index:3;right:-4.5%;top:-29%;width:auto!important;height:170%!important;object-fit:contain!important;object-position:center!important;opacity:.9;pointer-events:none;transform:none!important;filter:drop-shadow(0 0 20px rgba(232,24,72,.08));mix-blend-mode:screen;transition:opacity .35s var(--ease)}.hero-stage:hover .hero-slash{opacity:1}.hero-stage:after{content:"";position:absolute;z-index:2;inset:0;background:linear-gradient(180deg,transparent 48%,rgba(0,0,0,.22));pointer-events:none}.stage-label{position:absolute;z-index:4;left:22px;bottom:18px;padding:8px 11px;background:rgba(7,7,7,.72);font-size:10px;text-transform:uppercase;letter-spacing:.15em}
.manifesto{--m-title-y:0px;--m-copy-y:0px;--m-kicker-y:0px;--m-img1-y:0px;--m-img2-y:0px;--m-img1-inner-y:0px;--m-img2-inner-y:0px;--m-img1-x:0px;--m-img2-x:0px;--m-tilt1:0deg;--m-tilt2:0deg;background:var(--paper);color:var(--ink);padding:clamp(100px,11vw,180px) 0;position:relative;overflow:hidden}.manifesto-grid{display:grid;grid-template-columns:.38fr 1.62fr;gap:clamp(38px,7vw,118px);align-items:start}.manifesto-grid>.kicker{will-change:transform}.manifesto-grid>.kicker.reveal.in{transform:translate3d(0,var(--m-kicker-y),0)}.manifesto h2{font-size:clamp(50px,7.1vw,110px);line-height:.9;letter-spacing:-.065em;margin:0;max-width:1040px;font-weight:540;will-change:transform}.manifesto h2.reveal.in{transform:translate3d(0,var(--m-title-y),0)}.manifesto-copy{margin-top:clamp(42px,5vw,76px);display:grid;grid-template-columns:1fr 1fr;gap:36px;max-width:900px;transform:translate3d(0,var(--m-copy-y),0);will-change:transform}.manifesto-copy p{font-size:clamp(17px,1.25vw,21px);line-height:1.52;margin:0;color:#46433e}.manifesto-visual{margin-top:clamp(70px,8vw,120px);display:grid;grid-template-columns:1.2fr .8fr;gap:18px;position:relative;perspective:1400px}.manifesto-visual figure{margin:0;overflow:hidden;background:#ccc;position:relative;transform-origin:center center;will-change:transform}.manifesto-visual figure:first-child{aspect-ratio:1.5/1;transform:translate3d(var(--m-img1-x),var(--m-img1-y),0) rotate(var(--m-tilt1))}.manifesto-visual figure:last-child{aspect-ratio:1/1;transform:translate3d(var(--m-img2-x),var(--m-img2-y),0) rotate(var(--m-tilt2))}.manifesto-visual img{height:112%;width:112%;max-width:none;object-fit:cover;position:relative;left:-6%;top:-6%;transition:filter .7s var(--ease);will-change:transform}.manifesto-visual figure:first-child img{transform:scale(1.035) translate3d(0,var(--m-img1-inner-y),0)}.manifesto-visual figure:last-child img{object-position:50% 43%;transform:scale(1.045) translate3d(0,var(--m-img2-inner-y),0)}@media (hover:hover) and (poin