.tasks{background:var(--paper);color:var(--ink);padding:0 0 clamp(110px,12vw,190px)}.tasks-head{display:grid;grid-template-columns:.38fr 1.62fr;gap:clamp(38px,7vw,118px);padding-top:clamp(40px,5vw,74px);border-top:1px solid var(--line-dark)}.tasks h2{font-size:clamp(44px,5.3vw,84px);line-height:.94;letter-spacing:-.055em;margin:0;font-weight:540}.task-grid{display:grid;grid-template-columns:repeat(4,1fr);margin-top:clamp(54px,6vw,92px);border-top:1px solid var(--line-dark);border-left:1px solid var(--line-dark)}.task{min-height:280px;padding:22px 22px 26px;border-right:1px solid var(--line-dark);border-bottom:1px solid var(--line-dark);display:flex;flex-direction:column;justify-content:space-between;transition:background .25s}.task:hover{background:#e5e1db}.task-num{font-size:11px;color:#77736c}.task h3{font-size:clamp(28px,2.55vw,42px);line-height:.98;letter-spacing:-.045em;font-weight:520;margin:0}.task p{margin:16px 0 0;color:#5c5851;max-width:260px;font-size:14px}
.routes{padding:clamp(110px,12vw,190px) 0;background:#0a0a0a}.routes-head{display:grid;grid-template-columns:.38fr 1.62fr;gap:clamp(38px,7vw,118px);margin-bottom:clamp(60px,7vw,110px)}.routes-head h2{font-size:clamp(54px,6.6vw,104px);line-height:.9;letter-spacing:-.065em;margin:0;font-weight:540}.route-system{display:grid;grid-template-columns:.78fr 1.22fr;gap:clamp(42px,5vw,80px);align-items:start}.route-nav{position:sticky;top:120px;border-top:1px solid var(--line)}.route-tab{width:100%;background:none;border:0;border-bottom:1px solid var(--line);color:#777;padding:22px 0;display:grid;grid-template-columns:52px 1fr 20px;gap:10px;align-items:center;text-align:left;cursor:pointer;transition:color .25s}.route-tab:hover,.route-tab.active{color:white}.route-tab strong{font-size:clamp(21px,2vw,30px);font-weight:470;letter-spacing:-.035em}.route-tab em{font-style:normal;font-size:12px}.route-tab i{font-style:normal;text-align:right}.route-display{position:sticky;top:120px;min-height:650px}.route-panel{display:none;min-height:650px;grid-template-rows:auto 1fr;gap:28px}.route-panel.active{display:grid}.route-copy{display:grid;grid-template-columns:1.2fr .8fr;gap:40px;align-items:end}.route-copy h3{font-size:clamp(40px,4.8vw,78px);line-height:.92;letter-spacing:-.055em;margin:0;font-weight:520}.route-copy p{margin:0;color:#aaa59f;font-size:16px}.route-image{position:relative;overflow:hidden;background:#151515;min-height:410px}.route-image img{height:100%;object-fit:cover;transition:transform 1.1s var(--ease)}.route-panel.active .route-image img{animation:routeIn .9s var(--ease) both}.route-chip{position:absolute;right:16px;top:16px;background:rgba(7,7,7,.75);border:1px solid rgba(255,255,255,.15);padding:8px 10px;font-size:10px;text-transform:uppercase;letter-spacing:.15em}@keyframes routeIn{from{transform:scale(1.055);opacity:.65}to{transform:scale(1);opacity:1}}
.route-mobile{display:none}.route-card{border-top:1px solid var(--line);padding:28px 0}.route-card h3{font-size:35px;letter-spacing:-.045em;line-height:1;margin:0 0 16px}.route-card p{color:#aaa;margin:0 0 24px}.route-card img{margin:18px 0 20px;aspect-ratio:1.35/1;object-fit:cover}
