.foundation{background:var(--paper);color:var(--ink);padding:clamp(110px,12vw,190px) 0}.foundation-head{display:grid;grid-template-columns:.38fr 1.62fr;gap:clamp(38px,7vw,118px)}.foundation h2{font-size:clamp(52px,6.5vw,100px);line-height:.9;letter-spacing:-.065em;margin:0;font-weight:540}.foundation-copy{font-size:clamp(18px,1.35vw,22px);color:#4c4842;max-width:760px;margin-top:30px}.foundation-list{margin-top:clamp(60px,7vw,100px);border-top:1px solid var(--line-dark)}.foundation-row{display:grid;grid-template-columns:70px 1fr .75fr;gap:24px;padding:24px 0;border-bottom:1px solid var(--line-dark);align-items:center}.foundation-row .n{font-size:11px;color:#79746d}.foundation-row strong{min-width:0;overflow-wrap:anywhere;hyphens:auto;font-size:clamp(28px,3.15vw,48px);letter-spacing:-.045em;font-weight:500}.foundation-row span:last-child{min-width:0;overflow-wrap:anywhere;color:#625e57;font-size:14px}
