.reveal{opacity:0;transform:translateY(32px);transition:opacity .85s var(--ease),transform .85s var(--ease)}.reveal.in{opacity:1;transform:none}
@media (max-width:1020px){.nav-links{display:none}.menu-btn{display:flex;position:relative}.mobile-menu.open{display:block}.hero-bottom{grid-template-columns:1fr}.hero-actions{justify-content:flex-start}.manifesto-grid,.tasks-head,.routes-head,.foundation-head{grid-template-columns:1fr}.manifesto-grid>.kicker,.tasks-head>.kicker,.routes-head>.kicker,.foundation-head>.kicker{margin-bottom:4px}.manifesto-copy{max-width:none}.route-system{display:none}.route-mobile{display:block}.task-grid{grid-template-columns:1fr 1fr}.architecture-grid{grid-template-columns:1fr}.system-story{grid-template-columns:1fr;gap:50px}.system-visual{position:relative;top:auto}.system-image-frame{height:auto;min-height:0;aspect-ratio:1.35/1}.system-step{min-height:300px}.local-grid{grid-template-columns:1fr}.local-image{min-height:480px}.footer-top{grid-template-columns:1fr}.footer-map{grid-template-columns:repeat(3,1fr)}}
